import itertools
# regions of (lotus,daisy,tulip,sunflower)
regs=[r for r in itertools.product([0,1],repeat=4) if not(r[0] and r[1]) and (not r[0] or r[2]) and (not r[2] or r[3])]
models=[]
for n in range(1,len(regs)+1):
    for sub in itertools.combinations(regs,n):
        models.append(sub)
def some(m,f): return any(f(r) for r in m)
c1=lambda m: not some(m,lambda r:r[1] and not r[2])
c2=lambda m: some(m,lambda r:r[3] and r[1])
c3=lambda m: not some(m,lambda r:r[3] and r[1])
def always(f): return all(f(m) for m in models)
assert not always(c1) and not always(c2) and not always(c3)
assert always(lambda m:c2(m) or c3(m))
opts={'A':always(c2),'B':always(lambda m:c2(m) or c3(m)),'C':always(c1),'D':always(c3)}
assert opts['B'] and not opts['A'] and not opts['C'] and not opts['D']

