def fold(net):
    start=next(iter(net))
    # orientation: vectors for face normal, 'down' (row+1) dir, 'right' (col+1) dir
    res={}
    def neg(v): return tuple(-x for x in v)
    stack=[(start,(0,0,1),(0,-1,0),(1,0,0))]
    seen=set()
    while stack:
        c,n,d,r=stack.pop()
        if c in seen: continue
        seen.add(c); res[net[c]]=n
        (i,j)=c
        for (di,dj) in [(1,0),(-1,0),(0,1),(0,-1)]:
            nc=(i+di,j+dj)
            if nc not in net or nc in seen: continue
            if (di,dj)==(1,0): stack.append((nc,d,neg(n),r))
            if (di,dj)==(-1,0): stack.append((nc,neg(d),n,r))
            if (di,dj)==(0,1): stack.append((nc,r,d,neg(n)))
            if (di,dj)==(0,-1): stack.append((nc,neg(r),d,n))
    return res
